// Generated by scripts/build-lesson-bundles.cjs.
((globalThis, register) => {
'use strict';
globalThis.KENGURU_CHOICE_LAYOUTS = {};
'use strict';

globalThis.makeSubjectEdition = function (meta, rows) {
  const {subject, year, grade, contest, letters, tasksFile, answersFile, language} = meta;
  const folder = 'assets/' + subject + '/' + year + '/';
  const grades = grade.split('-').map(Number);
  const lessons = rows.map(row => {
    const {title, question, choices, figure, optionFigures, steps, context, audio, numericAnswer} = row;
    const options = choices.map((text, i) => {
      const image = optionFigures?.[i];
      if (!image) return {text};
      return {text: row.showOptionText ? text : '', image: image.src,
        description: row.showOptionText ? text + '. ' + image.alt : image.alt,
        ...(image.detailSrc ? {detailSrc: image.detailSrc} : {}),
        pixelWidth: image.width, pixelHeight: image.height};
    });
    return {
      title, question, choices, language, context, guided: true, hideIntroText: true,
      skill: contest, answer: row.answer ?? null,
      points: row.points ?? meta.points,
      ...(row.adaptation ? {questionNote: row.adaptation} : {}),
      ...(row.number ? {number: row.number} : {}),
      ...(Number.isInteger(numericAnswer) ? {numericAnswer} : {}),
      ...(audio ? {audio: folder + (meta.listeningFile ?? 'listening.mp3')} : {}),
      ...(figure || optionFigures ? {choiceLayout: {condition: figure, options},
        choiceImages: options.map(option => option.image),
        ...(figure ? {conditionImage: figure.src, conditionAlt: figure.alt} : {})} : {}),
      steps: [
        ['Выбор', 'Условие задачи', ''],
        ...steps.map((explanation, index) => index === steps.length - 1
          ? ['Проверка', 'Проверка', explanation]
          : [index ? 'Шаг ' + (index + 1) : 'Первый шаг', 'Рассуждение', explanation]),
        ['Ответ', 'Ответ', ''],
      ],
    };
  });
  for (const group of meta.matchingGroups ?? []) {
    const parts = lessons.slice(group.start - 1, group.start - 1 + group.count);
    if (parts.length !== group.count || parts.some(part => !part.conditionImage ||
        JSON.stringify(part.choices) !== JSON.stringify(parts[0].choices))) throw new Error('Incomplete matching group ' + group.title);
    const steps = [
      ['Выбор', 'Условие задачи', ''],
      ...parts.map((part, index) => ['Рисунок ' + (index + 1), part.title,
        part.steps.slice(1, -1).map(step => step[2]).join(' ')]),
      ['Ответ', 'Все пары', ''],
    ];
    for (const part of parts) Object.assign(part, {matching: group, title: group.title, question: group.question, steps});
  }
  return {
    id: [year, subject, meta.session, grade, meta.editionSuffix].filter(Boolean).join('-'), year, grades,
    label: grades.join('–') + (grades.length === 1 ? ' класс' : ' классы') + (meta.sessionTitle ? ' · ' + meta.sessionTitle : '') + (meta.editionLabel ? ' · ' + meta.editionLabel : ''),
    ...(meta.sections ? {sections: meta.sections} : {}),
    ...(meta.titleLanguage ? {titleLanguage: meta.titleLanguage} : {}),
    subject, answerLetters: [...letters], sources: {
      contest, tasksUrl: folder + tasksFile, answersUrl: folder + answersFile,
      ...(meta.reviewedKey ? {reviewedKey: true} : {}),
    },
    lessons, scenes: lessons.map(() => () => ''),
  };
};

register(globalThis.makeSubjectEdition({"subject":"golden-fleece","year":2024,"grade":"5-7","contest":"Золотое руно","letters":"ABCD","count":30,"language":"ru","points":3,"tasksFile":"zadanija-5-7_klassy.pdf","answersFile":"reviewed-5-7.pdf","reviewedKey":true}, [{"title":"Круг в символике","question":"Какое из этих понятий традиционно изображают колесом, обозначающим круг повторных рождений?","choices":["Сансару","Карму","Йогу","Нирвану"],"answer":0,"steps":["Если смерть ведёт к новому рождению, последовательность событий можно представить как замкнутый круг. В буддийских изображениях так устроено колесо бытия.","Круг перерождений называют сансарой. Карма связана с поступками, которые определяют, как продолжается этот круг."]},{"title":"Предок языковой семьи","question":"Как называют реконструированный общий предок индоевропейских языков, включая русский?","choices":["Праиндоевропейский язык","Санскрит","Хинди","Бенгали"],"answer":0,"steps":["Лингвисты сопоставляют древние и современные языки по тому, как в них менялись звуки, слова и грамматика. Это позволяет предположить, каким был язык, от которого они произошли.","Общий реконструированный предок называется праиндоевропейским. Санскрит относится к одной из ветвей семьи."]},{"title":"Индийская настольная игра","question":"Какая из этих древнеиндийских игр считается одной из предшественниц шахмат?","choices":["Чаупар","Лила","Чатуранга","Чопат"],"answer":2,"steps":["В старинной игре на клетчатом поле были фигуры, обозначавшие части войска: колесницы, конницу, слонов и пехоту.","Эти четыре части отражены в названии «чатуранга». Она связана с историей появления шахмат."]},{"title":"Выражение о почитании","question":"Какое устойчивое выражение связано с традицией почитания животных в Индии?","choices":["Волк в овечьей шкуре","Священная корова","Делать из мухи слона","Золотой телец"],"answer":1,"steps":["В индуистских традициях корову почитают за её связь с питанием и жизнью. Из буквального выражения возникло переносное.","«Священной коровой» в переносном смысле называют то, что принято оберегать от критики."]},{"title":"Традиционная медицина","question":"Как называется традиционная система медицины, развивавшаяся в Индии и распространённая в Южной Азии?","choices":["Ригведа","Аюрведа","Натьяшастра","Дханурведа"],"answer":1,"steps":["В названии нужной системы есть слово «веда», то есть «знание». Первая часть названия указывает на жизнь.","Аюрведа — традиционное учение о здоровье и образе жизни. Ригведа представляет собой собрание древних гимнов."]},{"title":"Спор двух ветвей рода","question":"Какой индийский эпос рассказывает о борьбе за власть между Пандавами и Кауравами?","choices":["Ригведа","Рамаяна","Махабхарата","Веды"],"answer":2,"steps":["В эпосе родственные ветви царского дома спорят о наследовании. Противостояние ведёт к битве на поле Курукшетра.","Это центральный сюжет «Махабхараты». «Рамаяна» повествует о Раме, Сите и войне с Раваной."]},{"title":"Древний город на Инде","question":"К какой цивилизации относят город Мохенджо-Даро?","choices":["Хеттской","Шумерской","Хараппской","Персидской"],"answer":2,"steps":["Руины Мохенджо-Даро находятся в долине Инда, на территории современного Пакистана. Там же обнаружены другие города бронзового века, включая Хараппу.","По имени Хараппы цивилизацию называют хараппской. Другое её название — Индская цивилизация."]},{"title":"Руины центра обучения","question":"Как назывался древний центр обучения на территории современного Пакистана, известный в том числе по сообщениям о походе Александра Македонского?","choices":["Митхила","Наланда","Такшашила","Викрамашила"],"answer":2,"steps":["Античное название места — Таксила. Археологи нашли здесь следы нескольких древних городов, в том числе руины улиц и зданий, как на фотографии.","Санскритское название Таксилы — Такшашила. С центром связаны и античные рассказы, и индийская традиция обучения."],"figure":{"src":"assets/golden-fleece/2024/5-7/08.webp","alt":"Развалины каменных сооружений на фоне долины и зелёных холмов","width":240,"height":211},"references":["https://whc.unesco.org/en/list/139"],"reviewedEdition":true},{"title":"Золотой храм Варанаси","question":"Какому богу посвящён храм Каши Вишванатха в Варанаси?","choices":["Индре","Брахме","Шиве","Кришне"],"answer":2,"steps":["Храм иногда называют Золотым из-за позолоченных верхних частей. Имя Вишванатха означает «владыка мира» и употребляется в Варанаси как одно из имён бога.","Так называют Шиву. По этой причине храм стал важным местом паломничества для его почитателей."]},{"title":"Лабиринт из коридоров","question":"Частью какого архитектурного комплекса является многоуровневый лабиринт Бхул Бхулайя?","choices":["Красный форт","Бара Имамбара","Хармандир-Сахиб","Тадж-Махал"],"answer":1,"steps":["Лабиринт состоит из проходов над главным залом здания в Лакхнау. Высоко расположенные узкие коридоры ведут к выходам на крышу.","Зал и лабиринт сооружены в Бара Имамбаре. На фотографии видна мечеть из этого же комплекса."],"figure":{"src":"assets/golden-fleece/2024/5-7/10.webp","alt":"Мечеть с куполами и высокими минаретами","width":211,"height":274}},{"title":"Розовый город","question":"Какой индийский город назван в честь основателя и известен розовым цветом зданий?","choices":["Агра","Джайпур","Мумбаи","Варанаси"],"answer":1,"steps":["Основателем города в 1727 году был Джай Сингх II. Цвет фасадов исторического центра дал городу прозвище «Розовый».","Имя основателя читается в названии Джайпур. Это столица Раджастхана."]},{"title":"Вера прихожан храма","question":"Для последователей какой религии Хармандир-Сахиб в Амритсаре — одна из главных святынь?","choices":["Кришнаизма","Буддизма","Ислама","Сикхизма"],"answer":3,"steps":["На фото храм с позолоченными стенами стоит посреди водоёма. Он находится в Пенджабе, где возникла религиозная традиция сикхских гуру.","Этот комплекс известен как Золотой храм Амритсара. Это одна из главных святынь сикхизма."],"figure":{"src":"assets/golden-fleece/2024/5-7/12.webp","alt":"Золотое здание посреди водоёма","width":206,"height":232}},{"title":"Место паломничества","question":"Какой город на берегу Ганга служит крупным центром индуистского паломничества?","choices":["Дели","Варанаси","Джайпур","Агра"],"answer":1,"steps":["Сначала отметим города на реках. Дели и Агра стоят на Ямуне, а в Джайпуре нет берега Ганга.","Варанаси стоит на Ганге. К реке в городе ведут ступени-гхаты, где паломники совершают омовения."]},{"title":"Буддийские росписи","question":"В каком пещерном комплексе Западной Индии сохранились росписи на сюжеты буддийских преданий?","choices":["Тадж-Махал","Хава-Махал","Кутб-Минар","Аджанта"],"answer":3,"steps":["На фотографии входы в помещения вырезаны прямо в скале. В обителях, созданных здесь, сохранились росписи с эпизодами жизни Будды и его прежних воплощений.","Это пещеры Аджанты в штате Махараштра. Остальные варианты обозначают наземные сооружения других городов."],"figure":{"src":"assets/golden-fleece/2024/5-7/14.webp","alt":"Вырезанный в скале фасад с арочным отверстием","width":242,"height":213}},{"title":"Танец о Кришне и Радхе","question":"В каком из этих классических танцев, возникшем в штате Манипур на северо-востоке Индии, исполняют рас-лилу о Кришне и Радхе?","choices":["Манипури","Бхаратнатьям","Кучипуди","Одисси"],"answer":0,"steps":["Рас-лила — танцевальное представление о Кришне, Радхе и пастушках. В Манипуре эта традиция получила собственную музыку, костюмы и движения.","Классический танец, выросший из традиций этого штата, называется манипури."],"references":["https://ccrtindia.gov.in/wp-content/uploads/2020/09/Pub_Dance_Manipuri.pdf","https://ccrtindia.gov.in/wp-content/uploads/2021/02/Odissi_Dance.pdf","https://ccrtindia.gov.in/literary-arts/"],"reviewedEdition":true},{"title":"Правила для мелодии","question":"Что организует рага в индийском искусстве?","choices":["Ландшафтный дизайн","Распорядок дня","Музыкальные произведения","Церемониальные процессии"],"answer":2,"steps":["В классическом исполнении музыкант может импровизировать. Для этого он следует набору звукорядов, характерных интонаций и направлений мелодического движения.","Такую мелодическую основу называют рагой. Она помогает организовать музыкальное произведение."]},{"title":"Шесть песен поэмы","question":"Почему в поэме Калидасы «Ритусамхара» шесть песен?","choices":["По числу времён года","По числу знаков зодиака","По числу вед","По числу упанишад"],"answer":0,"steps":["В песнях меняются природа и занятия людей. Одна часть описывает жару, другая — сезон дождей, другие следуют дальше по годовому кругу.","В традиционном индийском делении года выделяют шесть сезонов. Каждому из них соответствует песня поэмы."]},{"title":"Надписи на мавзолее","question":"Отрывки из какой священной книги написаны на Тадж-Махале?","choices":["Ветхого Завета","Евангелия","Корана","Ригведы"],"answer":2,"steps":["На порталах мавзолея использована арабская каллиграфия. Мавзолей построил мусульманский правитель Шах-Джахан.","Надписи содержат фрагменты Корана. Его текст служит источником отдельных строк на входах комплекса."],"figure":{"src":"assets/golden-fleece/2024/5-7/18.webp","alt":"Белый мавзолей с большим куполом и минаретами","width":213,"height":223}},{"title":"Книга об императоре","question":"Что представляет собой памятник литературы «Бабур-наме»?","choices":["Сборник религиозных гимнов","Сказание о подвигах аватары Вишну","Основные положения буддизма","Воспоминания императора Великих Моголов"],"answer":3,"steps":["Имя в заглавии принадлежит Бабуру, основателю империи Великих Моголов. В книге он рассказывает о собственной жизни, походах и местах, которые видел.","Поэтому «Бабур-наме» относят к мемуарам. Этот ответ объясняет и название, и содержание книги."]},{"title":"Переписка с Толстым","question":"Кто из этих общественных деятелей переписывался со Львом Толстым и говорил о его влиянии на свои взгляды?","choices":["Махатма Ганди","Джавахарлал Неру","Индира Ганди","Чандра Бос"],"answer":0,"steps":["В 1909–1910 годах Толстой обсуждал в письмах применение ненасильственного сопротивления. Его корреспондент тогда работал в Южной Африке.","Им был Мохандас Ганди, позже прославившийся в борьбе за независимость Индии. Мысли Толстого повлияли на его понимание ненасилия."]},{"title":"Большое полотно","question":"Где выставлена картина Верещагина с торжественным въездом принца Уэльского в Джайпур?","choices":["Индийский музей","Ганди Смрити","Музей искусств Киран Надар","Мемориал Виктории"],"answer":3,"steps":["На холсте длинное шествие изображено с большим количеством фигур. Оно посвящено визиту британского принца в 1876 году.","Это полотно хранится в Королевской галерее Мемориала Виктории в Калькутте. Музей называет его одним из крупнейших полотен на одном холсте."],"figure":{"src":"assets/golden-fleece/2024/5-7/21.webp","alt":"Картина с торжественным шествием людей и слонов","width":236,"height":155},"references":["https://victoriamemorial-cal.org/the-royal-gallery/oil-on-canvas-artist-vassili-verestchagin-the-prince-of-wales-later-king-edward-vii-at-jaipur-4-february-1876/"]},{"title":"Аромат в церемонии","question":"Какие предметы, используемые в индийских церемониях, называют агарбатти?","choices":["Благовония на бамбуковой палочке","Цветы лотоса на подносе","Ароматические свечи в подсвечниках","Корзины тропических фруктов"],"answer":0,"steps":["Предмет поджигают за конец. Когда пламя погасло, тлеющая смесь выделяет ароматный дым.","Агарбатти — благовонные палочки. Часто смесь наносится на тонкую основу из бамбука."]},{"title":"Путешественник из Твери","question":"Кого имел в виду Карамзин, говоря о раннем знакомстве Индии с Россией благодаря путешествию купца XV века?","choices":["А. Никитина","И. П. Минаева","С. И. Дежнёва","Е. П. Хабарова"],"answer":0,"steps":["На фото памятник человеку, написавшему «Хожение за три моря». Путь описан от Поволжья и Каспия к Индийскому океану.","Этим тверским купцом был Афанасий Никитин. Его записки сохранили впечатления о нескольких годах жизни в Индии."],"figure":{"src":"assets/golden-fleece/2024/5-7/23.webp","alt":"Статуя мужчины в длинной одежде на высоком постаменте","width":206,"height":299}},{"title":"Мангуст в литературе","question":"Кто использовал в своём произведении сюжет о мангусте и змее, известный по индийской «Панчатантре»?","choices":["Р. Киплинг","А. Линдгрен","Т. Янссон","Ш. Перро"],"answer":0,"steps":["В европейской версии мангуст защищает людей от кобр. Имя героя — Рикки-Тикки-Тави.","Рассказ с этим названием входит в «Книгу джунглей» Редьярда Киплинга. Мотив противостояния мангуста и змеи встречается и в индийской традиции."]},{"title":"Математик-самоучка","question":"Кто из индийских математиков с небольшим формальным обучением в начале карьеры стал членом Лондонского королевского общества?","choices":["Бхаскара I","Ганеш Прасад","Бхаскара II","Сриниваса Рамануджан"],"answer":3,"steps":["Этот математик отправил английскому учёному Годфри Харди письмо со своими результатами. Харди помог ему продолжить исследования в Кембридже.","Автором письма был Сриниваса Рамануджан. Его избрали в Королевское общество в 1918 году."],"references":["https://explore.trin.cam.ac.uk/assets/ramanujan/"],"reviewedEdition":true},{"title":"Эпическое сказание в стихах","question":"О ком рассказывает эпизод «Махабхараты», который перевёл Василий Жуковский?","choices":["О Раме","О Нале","О Куру","О Панду"],"answer":1,"steps":["В эпизоде царь теряет своё царство и разлучается с женой Дамаянти. Имена обоих героев стали заглавием русского переложения.","Оно называется «Наль и Дамаянти». Поэтому нужный герой — Наль."]},{"title":"Кого изобразил монумент","question":"Кого изобразили в памятнике «Статуя Единства» в индийском штате Гуджарат?","choices":["Махатму Ганди","Джавахарлала Неру","Валлабхаи Пателя","Рабиндраната Тагора"],"answer":2,"steps":["Название связано с объединением княжеств после обретения Индией независимости. Большую роль в этом сыграл первый министр внутренних дел страны.","Это Валлабхаи Патель, известный также как Сардар Патель. Его фигура изображена в монументе высотой 182 метра."]},{"title":"Массовый танец","question":"Какой индийский классический танец исполнили одновременно 7002 участника, установив рекорд Guinness?","choices":["Манипури","Бхаратнатьям","Кучипуди","Одисси"],"answer":2,"steps":["Рекорд установили в 2017 году в Вишакхапатнаме, городе штата Андхра-Прадеш. Именно с этим штатом связан один из стилей в списке.","Кучипуди назван в честь одноимённого поселения в Андхра-Прадеше. Его танцевали участники рекорда."],"references":["https://www.guinnessworldrecords.com/world-records/largest-kuchipudi-dance"]},{"title":"Кто может войти в храм","question":"Кто может молиться в показанном на фотографии Храме Лотоса в Нью-Дели?","choices":["Только мусульмане","Исключительно индуисты","Представители всех религий","Только буддисты"],"answer":2,"steps":["Белая крыша в форме цветка помогает узнать Дом поклонения бахаи. У домов поклонения этой религии есть правило открытости для всех посетителей.","Молиться в храме могут люди любой религии. Его посещение не связано с принадлежностью к определённой общине."],"figure":{"src":"assets/golden-fleece/2024/5-7/29.webp","alt":"Белое здание с крышей в форме раскрытых лепестков","width":211,"height":218},"references":["https://news.bahai.org/story/856/iconic-lotus-temple-focus-of-worldwide-campaign"]},{"title":"Город рождения Ганди","question":"В каком городе родился Мохандас Карамчанд Ганди, которого назвали Махатмой, «великой душой»?","choices":["Нью-Дели","Мумбаи","Бангалор","Порбандар"],"answer":3,"steps":["Ганди родился в 1869 году в приморском городе современного штата Гуджарат. Ищем этот город среди вариантов.","Подходит Порбандар, порт у Аравийского моря. В нём сохранился дом, где Ганди родился."]}]), globalThis.KENGURU_CHOICE_LAYOUTS, {});
})({KenguruVisual: globalThis.KenguruVisual}, globalThis.KenguruEditions.register);
